from __future__ import annotations; from pathlib import Path; from textwrap import dedent; import yaml; from common.meta.extension import migration_risk; ROOT = Path(__file__).resolve().parents[2]; read = lambda path: (ROOT / path).read_text(encoding='utf-8')
def write(path: Path, content: str) -> None: path.write_text(dedent(content).lstrip(), encoding='utf-8')
def write_manifest(path: Path, migrations: dict[str, object]) -> None: path.write_text(yaml.safe_dump({'version': 1, 'migrations': migrations}), encoding='utf-8')
def test_AC7_11_1_migration_risk_manifest_covers_backend_migrations() -> None: 'AC-meta.migration-risk.1 AC7.11.1'; result = migration_risk.validate_repository(ROOT); assert result.ok; assert result.errors == []; assert len(result.migrations) >= 40; assert result.manifest_path == ROOT / 'common/meta/data/migration-risk.yaml'; assert all((record.risk in migration_risk.RISK_LEVELS for record in result.migrations.values()))
def test_AC7_11_2_high_and_critical_migrations_require_release_proof(tmp_path: Path) -> None: 'AC-meta.migration-risk.2 AC7.11.2'; migrations_dir = tmp_path / 'migrations'; migrations_dir.mkdir(); (migrations_dir / '0001_high.py').write_text(dedent('\nfrom alembic import op\n\nrevision = "0001_high"\ndown_revision = None\n\ndef upgrade():\n    op.execute("UPDATE accounts SET name = name")\n').lstrip(), encoding='utf-8'); manifest = tmp_path / 'migration-risk.yaml'; manifest.write_text(yaml.safe_dump({'version': 1, 'migrations': {'0001_high': {'file': '0001_high.py', 'risk': 'high', 'proof': 'Data rewrite requires more than clean-schema proof.'}}}), encoding='utf-8'); result = migration_risk.validate(manifest_path=manifest, migrations_dir=migrations_dir); assert any(('0001_high' in error and 'staging_validation' in error for error in result.errors)); assert any(('0001_high' in error and 'production_preflight' in error for error in result.errors)); assert any(('0001_high' in error and 'rollback_strategy' in error for error in result.errors))
def test_AC7_11_3_destructive_migrations_must_be_classified_critical(tmp_path: Path) -> None: 'AC-meta.migration-risk.3 AC7.11.3'; migrations_dir = tmp_path / 'migrations'; migrations_dir.mkdir(); (migrations_dir / '0002_drop_legacy.py').write_text(dedent('\nfrom alembic import op\n\nrevision = "0002_drop_legacy"\ndown_revision = None\n\ndef upgrade():\n    op.drop_table("legacy_rows")\n').lstrip(), encoding='utf-8'); manifest = tmp_path / 'migration-risk.yaml'; manifest.write_text(yaml.safe_dump({'version': 1, 'migrations': {'0002_drop_legacy': {'file': '0002_drop_legacy.py', 'risk': 'high', 'proof': 'This intentionally under-classifies a destructive migration.', 'issue': '#815', 'staging_validation': 'Staging drop rehearsal.', 'production_preflight': 'Production table dependency check.', 'rollback_strategy': 'Backup before destructive change.'}}}), encoding='utf-8'); result = migration_risk.validate(manifest_path=manifest, migrations_dir=migrations_dir); assert any(('0002_drop_legacy' in error and 'critical' in error for error in result.errors)); 'AC7.11.3'; _m1_tmp = tmp_path / '_m1'; _m1_tmp.mkdir(exist_ok=True); 'AC7.11.3'; _m1_migrations_dir = _m1_tmp / 'migrations'; _m1_migrations_dir.mkdir(); _m1_missing_manifest = migration_risk.validate(manifest_path=_m1_tmp / 'missing.yaml', migrations_dir=_m1_migrations_dir); assert not _m1_missing_manifest.ok; assert any(('does not exist' in _m1_error for _m1_error in _m1_missing_manifest.errors)); _m1_invalid_yaml = _m1_tmp / 'invalid.yaml'; _m1_invalid_yaml.write_text('migrations: [', encoding='utf-8'); _m1_invalid_yaml_result = migration_risk.validate(manifest_path=_m1_invalid_yaml, migrations_dir=_m1_migrations_dir); assert any(('invalid YAML' in _m1_error for _m1_error in _m1_invalid_yaml_result.errors)); _m1_scalar_manifest = _m1_tmp / 'scalar.yaml'; _m1_scalar_manifest.write_text('[]', encoding='utf-8'); _m1_scalar_result = migration_risk.validate(manifest_path=_m1_scalar_manifest, migrations_dir=_m1_migrations_dir); assert any(('must be a YAML mapping' in _m1_error for _m1_error in _m1_scalar_result.errors)); _m1_missing_migrations_manifest = _m1_tmp / 'missing-migrations.yaml'; _m1_missing_migrations_manifest.write_text('version: 1\n', encoding='utf-8'); _m1_missing_migrations_result = migration_risk.validate(manifest_path=_m1_missing_migrations_manifest, migrations_dir=_m1_migrations_dir); assert any(("missing 'migrations' mapping" in _m1_error for _m1_error in _m1_missing_migrations_result.errors)); 'AC7.11.3'; _m2_tmp = tmp_path / '_m2'; _m2_tmp.mkdir(exist_ok=True); 'AC7.11.3'; _m2_migrations_dir = _m2_tmp / 'migrations'; _m2_migrations_dir.mkdir(); write(_m2_migrations_dir / 'bad_syntax.py', 'def upgrade(:\n    pass\n'); write(_m2_migrations_dir / 'missing_revision.py', '\n        down_revision = None\n\n        def upgrade():\n            pass\n        '); write(_m2_migrations_dir / 'dynamic_revision.py', '\n        revision = make_revision()\n        down_revision = None\n\n        def upgrade():\n            pass\n        '); write(_m2_migrations_dir / 'typed_revision.py', '\n        revision: str = "typed_revision"\n        down_revision = None\n\n        def upgrade():\n            pass\n        '); write(_m2_migrations_dir / 'no_upgrade.py', '\n        revision = "no_upgrade"\n        down_revision = None\n        '); write(_m2_migrations_dir / 'duplicate_a.py', '\n        revision = "duplicate_revision"\n        down_revision = None\n\n        def upgrade():\n            pass\n        '); write(_m2_migrations_dir / 'duplicate_b.py', '\n        revision = "duplicate_revision"\n        down_revision = None\n\n        def upgrade():\n            pass\n        '); write(_m2_migrations_dir / 'missing_manifest.py', '\n        from alembic import op\n\n        revision = "missing_manifest"\n        down_revision = None\n\n        def upgrade():\n            op.drop_table("legacy_rows")\n        '); _m2_manifest = _m2_tmp / 'migration-risk.yaml'; write_manifest(_m2_manifest, {'typed_revision': {'file': 'typed_revision.py', 'risk': 'low', 'proof': 'Typed revision assignment is accepted.'}, 'no_upgrade': {'file': 'no_upgrade.py', 'risk': 'low', 'proof': 'No upgrade function is accepted for merge-only style revisions.'}, 'duplicate_revision': {'file': 'duplicate_a.py', 'risk': 'low', 'proof': 'Only the first duplicate can be validated.'}, 'extra_revision': {'file': 'extra_revision.py', 'risk': 'low', 'proof': 'Extra manifest entries must be rejected.'}}); _m2_result = migration_risk.validate(manifest_path=_m2_manifest, migrations_dir=_m2_migrations_dir); assert any(('bad_syntax.py: cannot parse' in _m2_error for _m2_error in _m2_result.errors)); assert any(('missing_revision.py: missing string Alembic revision' in _m2_error for _m2_error in _m2_result.errors)); assert any(('dynamic_revision.py: missing string Alembic revision' in _m2_error for _m2_error in _m2_result.errors)); assert any(('duplicate Alembic revision' in _m2_error for _m2_error in _m2_result.errors)); assert any(('missing_manifest: auto-classified critical migration requires a manifest entry' in _m2_error for _m2_error in _m2_result.errors)); assert any(('extra_revision: manifest entry has no matching migration file' in _m2_error for _m2_error in _m2_result.errors)); assert _m2_result.migrations['typed_revision'].file_name == 'typed_revision.py'; assert _m2_result.migrations['no_upgrade'].proof.startswith('No upgrade'); 'AC7.11.3'; _m3_tmp = tmp_path / '_m3'; _m3_tmp.mkdir(exist_ok=True); 'AC7.11.3'; _m3_migrations_dir = _m3_tmp / 'migrations'; _m3_migrations_dir.mkdir(); write(_m3_migrations_dir / 'not_mapping.py', '\n        revision = "not_mapping"\n        down_revision = None\n\n        def upgrade():\n            pass\n        '); write(_m3_migrations_dir / 'bad_fields.py', '\n        revision = "bad_fields"\n        down_revision = None\n\n        def upgrade():\n            pass\n        '); write(_m3_migrations_dir / 'bad_issue.py', '\n        revision = "bad_issue"\n        down_revision = None\n\n        def upgrade():\n            pass\n        '); write(_m3_migrations_dir / 'low_update.py', '\n        from alembic import op\n\n        revision = "low_update"\n        down_revision = None\n\n        def upgrade():\n            op.execute("UPDATE accounts SET name = name")\n        '); write(_m3_migrations_dir / 'critical_drop.py', '\n        from alembic import op\n\n        revision = "critical_drop"\n        down_revision = None\n\n        def upgrade():\n            op.drop_column("legacy_rows", "legacy_value")\n        '); _m3_manifest = _m3_tmp / 'migration-risk.yaml'; write_manifest(_m3_manifest, {'not_mapping': 'bad', 'bad_fields': {'file': 'wrong.py', 'risk': 'extreme', 'proof': ' '}, 'bad_issue': {'file': 'bad_issue.py', 'risk': 'high', 'proof': 'High risk proof.', 'issue': '815', 'staging_validation': 'Staging proof.', 'production_preflight': 'Production preflight.', 'rollback_strategy': 'Rollback proof.'}, 'low_update': {'file': 'low_update.py', 'risk': 'low', 'proof': 'This intentionally under-classifies a data rewrite.'}, 'critical_drop': {'file': 'critical_drop.py', 'risk': 'critical', 'proof': 'Critical destructive migration proof.', 'issue': 'https://github.com/wangzitian0/finance_report/issues/815', 'staging_validation': 'Staging destructive proof.', 'production_preflight': 'Production dependency check.', 'rollback_strategy': 'Backup and restore strategy.', 'destructive_confirmation': 'Destructive operation explicitly confirmed.'}}); _m3_result = migration_risk.validate(manifest_path=_m3_manifest, migrations_dir=_m3_migrations_dir); assert any(('not_mapping: manifest entry must be a mapping' in _m3_error for _m3_error in _m3_result.errors)); assert any(('bad_fields: manifest file must be' in _m3_error for _m3_error in _m3_result.errors)); assert any(('bad_fields: risk must be one of' in _m3_error for _m3_error in _m3_result.errors)); assert any(('bad_fields: proof is required' in _m3_error for _m3_error in _m3_result.errors)); assert any(('bad_issue: issue must be a GitHub issue reference' in _m3_error for _m3_error in _m3_result.errors)); assert any(('low_update: data-mutating upgrade operation must be classified as high or critical' in _m3_error for _m3_error in _m3_result.errors)); assert _m3_result.migrations['critical_drop'].destructive_confirmation is not None
def test_AC7_11_4_summary_and_cli_paths_are_reported(tmp_path: Path, capsys) -> None: 'AC7.11.4'; migrations_dir = tmp_path / 'migrations'; migrations_dir.mkdir(); write(migrations_dir / '0001_low.py', '\n        revision = "0001_low"\n        down_revision = None\n\n        def upgrade():\n            pass\n        '); manifest = tmp_path / 'migration-risk.yaml'; write_manifest(manifest, {'0001_low': {'file': '0001_low.py', 'risk': 'low', 'proof': 'CLI success path proof.'}}); summary_path = tmp_path / 'ci-context' / 'migration-risk.md'; rc = migration_risk.main(['--repo-root', str(tmp_path), '--manifest', str(manifest), '--migrations-dir', str(migrations_dir), '--summary', str(summary_path)]); stdout = capsys.readouterr().out; assert rc == 0; assert 'Status: pass' in stdout; assert 'Status: pass' in summary_path.read_text(encoding='utf-8'); failed = migration_risk.main(['--repo-root', str(tmp_path), '--manifest', str(tmp_path / 'missing.yaml'), '--migrations-dir', str(migrations_dir)]); captured = capsys.readouterr(); assert failed == 1; assert 'Status: fail' in captured.err; summary = migration_risk.render_summary(migration_risk.ValidationResult(manifest_path=Path('manifest.yaml'), migrations_dir=Path('migrations'), migrations={'critical_manual': migration_risk.MigrationRecord(revision='critical_manual', file_name='critical_manual.py', risk='critical', proof='Manual summary proof without issue.')}, errors=['synthetic error'])); assert '`critical_manual`: critical - Manual summary proof without issue.' in summary; assert '- synthetic error' in summary
def test_AC7_11_4_ci_and_release_dry_run_execute_migration_risk_contract() -> None: 'AC-meta.migration-risk.4 AC7.11.4'; ci = read('.github/workflows/ci.yml'); assert 'Migration Risk Contract Check' in ci; assert 'python tools/check_migration_risk.py' in ci
def test_AC7_11_5_low_and_medium_migrations_are_auto_classified(tmp_path: Path) -> None: 'AC-meta.migration-risk.5 AC7.11.5'; assert migration_risk.classify_risk('op.create_table("t")') == 'low'; assert migration_risk.classify_risk("op.add_column('t', c)") == 'low'; assert migration_risk.classify_risk('op.alter_column("t", "c")') == 'medium'; assert migration_risk.classify_risk('op.execute("ALTER TYPE e ADD VALUE x")') == 'medium'; assert migration_risk.classify_risk('op.execute("UPDATE t SET c = 1")') == 'high'; assert migration_risk.classify_risk('op.drop_table("t")') == 'critical'; migrations_dir = tmp_path / 'migrations'; migrations_dir.mkdir(); write(migrations_dir / 'additive.py', '\n        from alembic import op\n\n        revision = "additive"\n        down_revision = None\n\n        def upgrade():\n            op.create_table("widgets")\n        '); write(migrations_dir / 'altered.py', '\n        from alembic import op\n\n        revision = "altered"\n        down_revision = "additive"\n\n        def upgrade():\n            op.alter_column("widgets", "name")\n        '); write(migrations_dir / 'mutated.py', '\n        from alembic import op\n\n        revision = "mutated"\n        down_revision = "altered"\n\n        def upgrade():\n            op.execute("UPDATE widgets SET name = name")\n        '); manifest = tmp_path / 'migration-risk.yaml'; write_manifest(manifest, {}); result = migration_risk.validate(manifest_path=manifest, migrations_dir=migrations_dir); assert result.migrations['additive'].risk == 'low'; assert result.migrations['altered'].risk == 'medium'; assert all(('additive' not in error for error in result.errors)); assert all(('altered' not in error for error in result.errors)); assert 'mutated' not in result.migrations; assert any(('mutated: auto-classified high migration requires a manifest entry' in error for error in result.errors))
